code='''from collections import deque, Counter
def transform(grid):
 h,w=len(grid),len(grid[0]); bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
 seen=set(); q=deque()
 for r in range(h):
  for c in range(w):
   if (r in (0,h-1) or c in (0,w-1)) and grid[r][c]==bg: seen.add((r,c)); q.append((r,c))
 while q:
  r,c=q.popleft()
  for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
   if 0<=nr<h and 0<=nc<w and grid[nr][nc]==bg and (nr,nc) not in seen: seen.add((nr,nc)); q.append((nr,nc))
 out=[[4 if grid[r][c]==bg and (r,c) not in seen else grid[r][c] for c in range(w)] for r in range(h)]
 # A straight stroke may cross an otherwise closed cavity; fill the cavity's full rectangular interior.
 colors=set(x for row in grid for x in row)-{bg}
 for col in colors:
  rs=[r for r in range(h) if any(grid[r][c]==col for c in range(w))]; cs=[c for c in range(w) if any(grid[r][c]==col for r in range(h))]
  # only small boxed components; detect rectangular frame on its bounding rectangle
  if len(rs)<3 or len(cs)<3: continue
  top,bot,left,right=min(rs),max(rs),min(cs),max(cs)
  if all(grid[top][c]==col and grid[bot][c]==col for c in range(left,right+1)) and all(grid[r][left]==col and grid[r][right]==col for r in range(top,bot+1)):
   for r in range(top+1,bot):
    for c in range(left+1,right): out[r][c]=4
 return out
'''
